// A recording mock of the Web Audio API. Every node creation, connect/disconnect, property
// read and write, AudioParam automation call, `performance.now()` call, `window` lookup
// and three.js warning lands in `ctx.__log` as one string. The same source runs under
// upstream three.js (harness/run_diff.mjs) and under MoonBit (src/audio/audio_mock_test.mbt,
// generated by tools/gen_mock.mjs).
//
// createMockAudio(options) returns the mock AudioContext. options = {
//   listenerParams: true    the native listener has positionX..upZ AudioParams (Chrome);
//                           false leaves only setPosition / setOrientation
//   pannerParams: true      the same for PannerNode positionX..orientationZ
//   detune: true            AudioBufferSourceNode has a `detune` AudioParam
// }
// Helpers (not logged): __setTime(t) sets currentTime, __setNow(ms) sets performance.now(),
// __buffer(duration), __mediaElement(), __mediaStream(), __end(sourceNode) fires `onended`,
// __note(label, value), __installWindow(kind) sets globalThis.window ('standard', 'webkit'),
// __warn(message) records a warning, __captureConsole() routes MoonBit's `THREE.` println
// lines into the log, __finish() undoes the global patches and returns the log.

function createMockAudio(options) {
  options = options || {};
  const opt = (k) => options[k] !== false;
  const log = [];
  let nextId = 0;
  let currentTime = 0;
  let nowMs = 0;

  function fmt(v) {
    if (v === undefined) return 'undefined';
    if (v === null) return 'null';
    if (typeof v === 'number') return Object.is(v, -0) ? '-0' : String(v);
    if (typeof v === 'string') return JSON.stringify(v);
    if (typeof v === 'boolean') return String(v);
    if (typeof v === 'function') return 'function';
    if (typeof v === 'object' && typeof v.__id === 'string') return v.__id;
    if (ArrayBuffer.isView(v)) return v.constructor.name + '[' + Array.prototype.join.call(v, ',') + ']';
    if (Array.isArray(v)) return '[' + v.map(fmt).join(', ') + ']';
    return 'object';
  }

  function make(kind) {
    const o = {};
    Object.defineProperty(o, '__id', { value: kind + '#' + nextId++ });
    return o;
  }
  function prop(o, name, initial, hooks) {
    let value = initial;
    Object.defineProperty(o, name, {
      enumerable: true,
      get() {
        log.push('get ' + o.__id + '.' + name + ' -> ' + fmt(value));
        return value;
      },
      set(v) {
        log.push('set ' + o.__id + '.' + name + ' = ' + fmt(v));
        if (hooks && hooks.readonly) return;
        value = v;
        if (hooks && hooks.onSet) hooks.onSet(v);
      },
    });
    return { peek: () => value };
  }
  function method(o, name, impl) {
    Object.defineProperty(o, name, {
      value: function (...args) {
        const r = impl ? impl.apply(o, args) : undefined;
        log.push(o.__id + '.' + name + '(' + args.map(fmt).join(', ') + ')' + (r === undefined ? '' : ' -> ' + fmt(r)));
        return r;
      },
    });
  }
  function param(owner, name, value) {
    const p = {};
    Object.defineProperty(p, '__id', { value: owner.__id + '.' + name });
    prop(p, 'value', value);
    method(p, 'setTargetAtTime', function () { return p; });
    method(p, 'linearRampToValueAtTime', function () { return p; });
    prop(owner, name, p, { readonly: true });
    return p;
  }
  function node(kind) {
    const n = make(kind);
    method(n, 'connect', (dest) => dest);
    method(n, 'disconnect');
    return n;
  }

  const ctx = make('AudioContext');
  // currentTime is driven by __setTime, read through the logging getter
  Object.defineProperty(ctx, 'currentTime', {
    get() { log.push('get ' + ctx.__id + '.currentTime -> ' + fmt(currentTime)); return currentTime; },
  });
  const destination = node('AudioDestinationNode');
  prop(ctx, 'destination', destination, { readonly: true });
  const listener = make('AudioListener');
  for (const [name, value] of [['positionX', 0], ['positionY', 0], ['positionZ', 0], ['forwardX', 0], ['forwardY', 0], ['forwardZ', -1], ['upX', 0], ['upY', 1], ['upZ', 0]]) {
    if (opt('listenerParams')) param(listener, name, value);
    else prop(listener, name, undefined, { readonly: true });
  }
  method(listener, 'setPosition');
  method(listener, 'setOrientation');
  prop(ctx, 'listener', listener, { readonly: true });

  method(ctx, 'createGain', () => {
    const n = node('GainNode');
    param(n, 'gain', 1);
    return n;
  });
  method(ctx, 'createPanner', () => {
    const n = node('PannerNode');
    prop(n, 'panningModel', 'equalpower');
    prop(n, 'distanceModel', 'inverse');
    prop(n, 'refDistance', 1);
    prop(n, 'maxDistance', 10000);
    prop(n, 'rolloffFactor', 1);
    prop(n, 'coneInnerAngle', 360);
    prop(n, 'coneOuterAngle', 360);
    prop(n, 'coneOuterGain', 0);
    for (const [name, value] of [['positionX', 0], ['positionY', 0], ['positionZ', 0], ['orientationX', 1], ['orientationY', 0], ['orientationZ', 0]]) {
      if (opt('pannerParams')) param(n, name, value);
      else prop(n, name, undefined, { readonly: true });
    }
    method(n, 'setPosition');
    method(n, 'setOrientation');
    return n;
  });
  method(ctx, 'createBufferSource', () => {
    const n = node('AudioBufferSourceNode');
    prop(n, 'buffer', null);
    prop(n, 'loop', false);
    prop(n, 'loopStart', 0);
    prop(n, 'loopEnd', 0);
    const onended = prop(n, 'onended', null);
    if (opt('detune')) param(n, 'detune', 0);
    else prop(n, 'detune', undefined, { readonly: true });
    param(n, 'playbackRate', 1);
    method(n, 'start');
    method(n, 'stop');
    Object.defineProperty(n, '__fireEnded', {
      value() {
        const handler = onended.peek();
        log.push('event ' + n.__id + ' ended' + (typeof handler === 'function' ? '' : ' (no handler)'));
        if (typeof handler === 'function') handler.call(n, { type: 'ended' });
      },
    });
    return n;
  });
  method(ctx, 'createAnalyser', () => {
    const n = node('AnalyserNode');
    let calls = 0;
    let bins = 1024;
    Object.defineProperty(n, 'frequencyBinCount', {
      get() { log.push('get ' + n.__id + '.frequencyBinCount -> ' + fmt(bins)); return bins; },
    });
    prop(n, 'fftSize', 2048, { onSet: (v) => { bins = v / 2; } });
    method(n, 'getByteFrequencyData', (array) => {
      calls++;
      for (let i = 0; i < array.length; i++) array[i] = (i * 37 + calls * 101 + 13) % 256;
    });
    return n;
  });
  method(ctx, 'createBiquadFilter', () => {
    const n = node('BiquadFilterNode');
    prop(n, 'type', 'lowpass');
    param(n, 'frequency', 350);
    return n;
  });
  method(ctx, 'createOscillator', () => {
    const n = node('OscillatorNode');
    param(n, 'frequency', 440);
    param(n, 'detune', 0);
    return n;
  });
  method(ctx, 'createMediaElementSource', () => node('MediaElementAudioSourceNode'));
  method(ctx, 'createMediaStreamSource', () => node('MediaStreamAudioSourceNode'));

  const saved = {};
  const hidden = (name, value) => Object.defineProperty(ctx, name, { value });
  hidden('__log', log);
  hidden('__setTime', (t) => { currentTime = t; });
  hidden('__setNow', (ms) => {
    nowMs = ms;
    if (!('now' in saved)) {
      saved.now = performance.now;
      performance.now = () => { log.push('performance.now() -> ' + fmt(nowMs)); return nowMs; };
    }
  });
  hidden('__buffer', (duration) => {
    const b = make('AudioBuffer');
    prop(b, 'duration', duration, { readonly: true });
    return b;
  });
  hidden('__mediaElement', () => make('HTMLMediaElement'));
  hidden('__mediaStream', () => make('MediaStream'));
  hidden('__end', (source) => source.__fireEnded());
  hidden('__note', (label, value) => { log.push('note ' + label + ' ' + fmt(value)); });
  hidden('__warn', (message) => { log.push('warn ' + message); });
  hidden('__installWindow', (kind) => {
    if (!('window' in saved)) saved.window = globalThis.window;
    const win = {};
    const ctor = function () { log.push('new window.' + (kind === 'webkit' ? 'webkitAudioContext' : 'AudioContext') + '()'); return ctx; };
    Object.defineProperty(win, 'AudioContext', {
      get() { const v = kind === 'webkit' ? undefined : ctor; log.push('get window.AudioContext -> ' + (v ? 'function' : 'undefined')); return v; },
    });
    Object.defineProperty(win, 'webkitAudioContext', {
      get() { log.push('get window.webkitAudioContext -> function'); return ctor; },
    });
    globalThis.window = win;
  });
  hidden('__captureConsole', () => {
    if ('log' in saved) return;
    saved.log = console.log;
    console.log = (...args) => {
      const s = args.join(' ');
      if (s.startsWith('THREE.')) log.push('warn ' + s);
      else saved.log(...args);
    };
  });
  hidden('__finish', () => {
    if ('now' in saved) performance.now = saved.now;
    if ('log' in saved) console.log = saved.log;
    if ('window' in saved) globalThis.window = saved.window;
    for (const k of Object.keys(saved)) delete saved[k];
    return log;
  });
  return ctx;
}
